PREFIX dct: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX moose: <https://moosedev.dev/kg/ontology/software-architecture/>
SELECT ?old ?oldLabel ?oldType ?new ?newLabel ?newType ?oldStatus ?newStatus WHERE {
  ?new moose:supersedes ?old .
  OPTIONAL { ?old rdfs:label ?oldLabel }
  OPTIONAL { ?new rdfs:label ?newLabel }
  OPTIONAL { ?old a ?oldType }
  OPTIONAL { ?new a ?newType }
  OPTIONAL { ?old moose:lifecycleStatus ?oldStatus }
  OPTIONAL { ?new moose:lifecycleStatus ?newStatus }
}
ORDER BY LCASE(STR(?oldLabel)) LCASE(STR(?newLabel))

